        else: raise HTTPException(403,'Installation access exceeds supported pagination limit')
        return repos

    def authorize(self,user,repository,write=False):
        for repo in self.repositories(user):
            if repo['full_name'].lower()==repository.lower():
                permissions=repo['app_permissions']
                if permissions.get('contents') not in {'read','write'} or permissions.get('issues') not in {'read','write'}:
                    raise HTTPException(403,'App requires Contents and Issues read permissions')
                if write and (not repo['permissions'].get('push') or permissions.get('contents')!='write' or permissions.get('pull_requests')!='write'):
                    raise HTTPException(403,'User and GitHub App require Contents and Pull requests write access')
                return self.token(user)
        raise HTTPException(403,'Install Torque GitHub App on this repository before using it')

    def authenticate(self,request):
