        if (!alive) return;
        if (e instanceof ApiError && e.status === 401) { setExpired(true); setSession(null); return; }
        setError(e instanceof Error ? e.message : 'Progress unavailable.');
        if (e instanceof ApiError && e.status === 404) return;
